const watchlist = $node['Lire WATCHLIST_BRVM'].json;
const portefeuille = $node['Lire PORTEFEUILLE'].json;
const journal = $node['Lire JOURNAL_DECISIONS (30 derniers jours)'].json;
const alertes = $node['Lire ALERTES de la semaine'].json;

// Filtrer le journal des 30 derniers jours
const il_y_a_30j = new Date();
il_y_a_30j.setDate(il_y_a_30j.getDate() - 30);

const journalRecent = Array.isArray(journal) 
  ? journal.filter(row => new Date(row.date) > il_y_a_30j)
  : [];

// Filtrer les alertes de la semaine
const il_y_a_7j = new Date();
il_y_a_7j.setDate(il_y_a_7j.getDate() - 7);

const alertesRecentes = Array.isArray(alertes)
  ? alertes.filter(row => new Date(row.date) > il_y_a_7j)
  : [];

// Calculer performance portefeuille
let valeurTotale = 0;
let coutTotal = 0;
if (Array.isArray(portefeuille)) {
  portefeuille.forEach(ligne => {
    valeurTotale += parseFloat(ligne.valeur_actuelle || 0);
    coutTotal += parseFloat(ligne.montant_investi || 0);
  });
}

const numSemaine = getISOWeek(new Date());
const annee = new Date().getFullYear();

function getISOWeek(date) {
  const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
  const dayNum = d.getUTCDay() || 7;
  d.setUTCDate(d.getUTCDate() + 4 - dayNum);
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  return Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
}

return [{
  json: {
    semaine: `Semaine ${numSemaine} - ${annee}`,
    watchlist: watchlist,
    portefeuille: portefeuille,
    journalRecent: journalRecent,
    alertesRecentes: alertesRecentes,
    stats: {
      valeurTotale: valeurTotale.toFixed(0),
      coutTotal: coutTotal.toFixed(0),
      gainPerte: (valeurTotale - coutTotal).toFixed(0),
      gainPertePct: coutTotal > 0 ? ((valeurTotale - coutTotal) / coutTotal * 100).toFixed(2) : 0
    }
  }
}];

const reponse = $input.first().json.text || $input.first().json.content || '';
const semaine = $node['Préparer contexte pour agent'].json.semaine;

let rapport;
try {
  const jsonMatch = reponse.match(/\{[\s\S]*\}/);
  rapport = jsonMatch ? JSON.parse(jsonMatch[0]) : {};
} catch(e) {
  rapport = { resume_marche: reponse };
}

rapport.semaine = rapport.semaine || semaine;
rapport.date_rapport = new Date().toISOString();

return [{ json: rapport }];

const r = $input.first().json;

const decisionsEmoji = {
  'attendre': '⏸️',
  'surveiller': '👁️',
  'achat_progressif_possible': '🟢',
  'achat_progressif': '🟢',
  'eviter': '🔴'
};

const emoji = decisionsEmoji[r.decision_recommandee] || '⚪';

const surveiller = (r.actions_a_surveiller || []).slice(0, 3).map(a => `  • ${a}`).join('\n');
const risques = (r.risques_identified || r.risques_identifies || []).slice(0, 3).map(r => `  ⚠️ ${r}`).join('\n');
const actions = (r.actions_concretes || []).slice(0, 3).map(a => `  ✓ ${a}`).join('\n');

const message = `📋 *Rapport Hebdomadaire — ${r.semaine || ''}*

📊 *Ce qui s'est passé :*
${(r.ce_qui_sest_passe || r.resume_marche || '').substring(0, 500)}

🔍 *Actions à surveiller :*
${surveiller || '  Aucune cette semaine'}

⚠️ *Risques identifiés :*
${risques || '  Aucun risque majeur'}

💼 *Mon portefeuille :*
${(r.etat_portefeuille || '').substring(0, 300)}

${emoji} *Décision recommandée : ${(r.decision_recommandee || '').toUpperCase()}*
_${(r.justification_decision || '').substring(0, 300)}_

✅ *Actions concrètes :*
${actions || '  Aucune action requise'}

📚 *Ce que j'ai appris :*
${(r.note_apprentissage || '').substring(0, 300)}

─────────────────
💡 _Analyse informative. Vous êtes le seul décisionnaire._
🏦 _Investisseur Afrique BRVM_`;

return [{ json: { message } }];
